 *   真太阳时 —— 修正经度时差与均时差后的当地真实太阳时
 *
 * 传统上八字（子平法）多用真太阳时，紫微斗数多按钟表时定时辰。
 * 如果各排各的，就会出现：
 *   同一个人，八字算出的时柱是「庚寅」，紫微算出的是「辛卯」，
 *   两个体系在算【不同的盘】，那"印证"就毫无意义。
 *
 * 所以本模块把时间基准【显式化并统一】：先算出两个口径，
 * 挑一个作为 adopted，然后把同一个时刻交给所有体系。
 * 口径差异作为数据暴露出去（不藏起来），由上层决定怎么向用户说明。
 */

const astro = require('./astro.js');

/**
 * 均时差（分钟）= 真太阳时 − 平太阳时
 * Meeus ch.28：E = L0 − 0.0057183° − α☉
 *   L0 取 ch.25 的太阳几何平黄经。
 * 标定：四个已知锚点误差 < 0.05 分钟 ——
 *   2/11 −14.18 (期望 −14.2) / 5/14 +3.66 (3.7)
 *   7/26  −6.55 (−6.5)       / 11/3 +16.45 (16.4)
 */
function equationOfTime(jd) {
  const T = (jd - 2451545.0) / 36525;
  const L0 = astro.norm360(280.46646 + 36000.76983 * T + 0.0003032 * T * T);
  const eps = astro.obliquity(jd);
  const ra = astro.toEquatorial(astro.sunLongitude(jd), eps).ra;
  let e = L0 - 0.0057183 - ra;
  e = ((e + 180) % 360 + 360) % 360 - 180;
  return e * 4;
}

