    y: t.getUTCFullYear(),
    m: t.getUTCMonth() + 1,
    d: t.getUTCDate(),
    h: t.getUTCHours(),
    mi: t.getUTCMinutes(),
    dayShift: Math.round((Date.UTC(t.getUTCFullYear(), t.getUTCMonth(), t.getUTCDate())
